import json,re
async def s(q,n=4,m=900,kw=None):
    r=json.loads(await web_search({"query":q}))
    print("##",q)
    for x in r[:n]:
        c=x['content']
        print(x['url']);
        if kw:
            for k in kw:
                for mm in list(re.finditer(k,c))[:2]:
                    print("  ..",c[max(0,mm.start()-150):mm.start()+250].replace("\n"," "))
        else: print(c[:m].replace("\n"," "))
await s("AB InBev FY2024 results revenue 59 768 million USD normalized EBITDA profit attributable net debt 31 December 2024",kw=["Revenue","Net debt","attributable"])

